/**
 * Lockfiles are regenerated by an install, which needs the network the agent
 * doesn't have, so prkit never lets an agent hand-merge one.
 */
const LOCKFILES = new Set([
  "pnpm-lock.yaml",
  "package-lock.json",
  "npm-shrinkwrap.json",
  "yarn.lock",
  "bun.lock",
  "bun.lockb",
  "deno.lock",
  "Cargo.lock",
  "Gemfile.lock",
  "poetry.lock",
  "uv.lock",
  "Pipfile.lock",
  "composer.lock",
  "go.sum",
  "mix.lock",
  "pubspec.lock",
  "Podfile.lock",
  "flake.lock",
]);

export const isLockfile = (path: string) => LOCKFILES.has(path.slice(path.lastIndexOf("/") + 1));

/** The 1-based lines of a file that are conflict markers git wrote. */
export const markerLines = (text: string) =>
  text
    .split("\n")
    .flatMap((line, index) =>
      /^(<{7}|>{7}|\|{7})( |$)/.test(line) || /^={7}$/.test(line) ? [index + 1] : [],
    );

/**
 * Who resolves a conflicted file. The agent edits text conflicts; prkit keeps the
 * base side of lockfiles, binary files and files one side deleted, and leaves
 * them for the owner.
 */
export const needsHuman = (file: {
  readonly path: string;
  readonly kind: "text" | "binary" | "deleted";
}) => file.kind !== "text" || isLockfile(file.path);
